const fs = require('fs');
const zlib = require('zlib');
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Parse ZIP manually - find local file headers
let offset = 0;
while (offset < buf.length) {
  if (buf.readUInt32LE(offset) !== 0x04034b50) break; // PK\x03\x04
  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const uncompSize = buf.readUInt32LE(offset + 22);
  const nameLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const name = buf.toString('utf8', offset + 30, offset + 30 + nameLen);
  const dataStart = offset + 30 + nameLen + extraLen;

  if (name === 'word/document.xml') {
    let data;
    if (compMethod === 0) {
      data = buf.slice(dataStart, dataStart + compSize);
    } else {
      data = zlib.inflateRawSync(buf.slice(dataStart, dataStart + compSize));
    }
    const xml = data.toString('utf8');
    const lines = xml.split(/<w:p[ >\/]/);
